    22→| `api.quiz.$id.tsx` | GET | Fetch quiz data for storefront rendering |
    23→| `api.submit.tsx` | POST | Submit quiz responses, return recommendations |
    24→| `api.widget-config.tsx` | GET | Fetch widget styling/configuration |
    25→| `api.products.tsx` | GET | Fetch recommended products for a quiz response |
    26→| `api.analytics.tsx` | POST | Track analytics events from the widget |
    27→
    28→## CORS Headers (Required on ALL endpoints)
    29→
    30→```typescript
    31→function corsHeaders(origin?: string): HeadersInit {
    32→  return {
    33→    "Access-Control-Allow-Origin": origin || "*",
    34→    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    35→    "Access-Control-Allow-Headers": "Content-Type",
    36→    "Access-Control-Max-Age": "86400",
    37→    "Content-Type": "application/json",
    38→  };
    39→}
    40→
    41→// Every route must handle OPTIONS preflight
    42→export async function loader({ request }: LoaderFunctionArgs) {
    43→  if (request.method === "OPTIONS") {
    44→    return new Response(null, { status: 204, headers: corsHeaders() });
    45→  }
    46→  // ...actual handler
    47→}
    48→```
    49→
    50→## Shop Validation
    51→
    52→Since these are public endpoints (no Shopify session), validate the shop parameter to prevent abuse.
    53→
    54→```typescript
    55→function validateShop(shop: string | null): string {
    56→  if (!shop) throw new Response("Missing shop parameter", { status: 400 });
    57→  // Validate format: must be *.myshopify.com
    58→  const shopRegex = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
    59→  if (!shopRegex.test(shop)) throw new Response("Invalid shop", { status: 400 });
    60→  return shop;
    61→}
    62→```
