    64→## Endpoint Implementations
    65→
    66→### GET api.quiz.$id.tsx — Fetch Quiz
    67→
    68→```typescript
    69→export async function loader({ request, params }: LoaderFunctionArgs) {
    70→  if (request.method === "OPTIONS") return corsResponse();
    71→  const url = new URL(request.url);
    72→  const shop = validateShop(url.searchParams.get("shop"));
    73→  const quiz = await db.quiz.findFirst({
    74→    where: { id: params.id, shop, status: "active" },
    75→    include: {
    76→      questions: {
    77→        orderBy: { position: "asc" },
    78→        include: { answers: { orderBy: { position: "asc" } } },
    79→      },
    80→    },
    81→  });
    82→  if (!quiz) return json({ error: "Quiz not found" }, { status: 404, headers: corsHeaders() });
    83→  // Strip internal fields (logic JSON, etc.) from public response
    84→  const sanitized = sanitizeQuizForPublic(quiz);
    85→  // Increment startCount
    86→  await db.quiz.update({ where: { id: quiz.id }, data: { startCount: { increment: 1 } } });
    87→  return json({ quiz: sanitized }, { headers: corsHeaders() });
    88→}
    89→```
