    93→```typescript
    94→export async function action({ request }: ActionFunctionArgs) {
    95→  if (request.method === "OPTIONS") return corsResponse();
    96→  const body = await request.json();
    97→  const { quizId, shop: rawShop, answers, sessionId } = body;
    98→  const shop = validateShop(rawShop);
    99→
   100→  // Validate quiz exists and is active
   101→  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop, status: "active" } });
   102→  if (!quiz) return json({ error: "Quiz not found" }, { status: 404, headers: corsHeaders() });
