   104→  // Collect tags from answers
   105→  const responseTags = collectTags(answers);
   106→
   107→  // Score products
   108→  const productMappings = await db.productMapping.findMany({ where: { quizId, status: "active" } });
   109→  const recommendations = scoreProducts(responseTags, productMappings, quiz.type);
   110→
   111→  // Save response and increment completions
   112→  await db.$transaction([
   113→    db.quizResponse.create({ data: { quizId, sessionId, answers: JSON.stringify(answers), tags: JSON.stringify(responseTags) } }),
   114→    db.quiz.update({ where: { id: quizId }, data: { completions: { increment: 1 } } }),
   115→  ]);
   116→
   117→  return json({ recommendations: recommendations.slice(0, maxProducts) }, { headers: corsHeaders() });
   118→}
   119→```
   120→
   121→### POST api.analytics.tsx — Track Events
   122→
   123→```typescript
   124→export async function action({ request }: ActionFunctionArgs) {
   125→  if (request.method === "OPTIONS") return corsResponse();
   126→  const body = await request.json();
   127→  const { quizId, shop: rawShop, sessionId, eventType, metadata } = body;
   128→  const shop = validateShop(rawShop);
   129→
   130→  // Validate event type
   131→  const validEvents = ["quiz-start", "question-view", "question-answer", "quiz-complete", "result-view", "product-click", "add-to-cart", "email-capture"];
   132→  if (!validEvents.includes(eventType)) {
   133→    return json({ error: "Invalid event type" }, { status: 400, headers: corsHeaders() });
   134→  }
   135→
   136→  await db.analyticsEvent.create({
   137→    data: { quizId, sessionId, eventType, metadata: JSON.stringify(metadata || {}) },
   138→  });
   139→
   140→  return json({ success: true }, { headers: corsHeaders() });
   141→}
   142→```
   143→
   144→## Input Sanitization
   145→
   146→```typescript
   147→function sanitizeString(input: string, maxLength: number = 1000): string {
   148→  return input.replace(/<[^>]*>/g, "").trim().slice(0, maxLength);
   149→}
   150→
   151→function sanitizeAnswers(answers: unknown): Record<string, string>[] {
   152→  if (!Array.isArray(answers)) throw new Response("Invalid answers", { status: 400 });
   153→  return answers.map((a) => ({
   154→    questionId: sanitizeString(String(a.questionId), 50),
   155→    value: sanitizeString(String(a.value), 500),
   156→  }));
   157→}
   158→```
   159→
   160→## Rate Limiting Awareness
   161→
   162→These public endpoints are exposed to the internet. Implement basic protections:
   163→- Validate all input parameters strictly.
   164→- Limit response payload size (max 50 products in recommendations).
   165→- Use DB connection pooling to prevent exhaustion.
   166→- Log suspicious patterns (many requests from same IP to same quiz).
   167→- Consider Cloudflare or similar for DDoS protection in production.
   168→
   169→## Collaboration Protocol
   170→
   171→- **Hand off to `storefront-builder`** for the widget that consumes these APIs.
   172→- **Hand off to `recommendation-engine`** for product scoring logic used in api.submit.tsx.
   173→- **Hand off to `analytics-builder`** for event validation and metric calculations.
   174→- **Hand off to `results-builder`** for result page data formatting.
   175→- **Hand off to `quiz-builder`** when API needs quiz-level data or status checks.
   176→
   177→## Self-Validation Checklist
   178→
   179→- [ ] Every endpoint returns CORS headers on all responses (including errors).
   180→- [ ] Every endpoint handles OPTIONS preflight requests.
   181→- [ ] Shop parameter is validated on every request.
   182→- [ ] No Shopify admin auth used — these are public endpoints.
   183→- [ ] Only active quizzes are returned — never draft or archived.
   184→- [ ] All input is sanitized before use.
   185→- [ ] Error responses use proper HTTP status codes with JSON bodies.
   186→- [ ] Internal data (logic rules, scoring weights) is stripped from public responses.
   187→- [ ] Response payloads are size-bounded.
   188→- [ ] Database queries use indexed fields for performance.
   189→
   190→## Never
   191→
   192→- Never use `shopify.authenticate.admin()` in API routes — they are public.
   193→- Never return draft or archived quizzes from the public API.
   194→- Never expose internal scoring logic, weights, or logic rules in API responses.
   195→- Never skip CORS headers — the widget makes cross-origin requests.
   196→- Never trust client input without sanitization.
   197→- Never return unbounded result sets — always limit/paginate.
   198→- Never log PII (emails, IPs) in plain text.
